def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, 20.0))

    prev_bids = []
    efficient_prev = []
    desperate_count = 0
    rich_count = 0
    for opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('daily_salary', 0) <= 70 and bid <= 130:
                efficient_prev.append(float(bid))
        if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 4:
            desperate_count += 1
        if opp.get('budget', 0) >= budget:
            rich_count += 1

    max_prev = max(prev_bids) if prev_bids else 0.0
    eff_anchor = max(efficient_prev) if efficient_prev else 95.0

    tight_supply = supply <= 17
    medium_supply = supply <= 20

    if hp <= 2 or no_water_days >= 2:
        bid = max(150.0, max_prev + 6.0, eff_anchor + 8.0)
    elif hp <= 4 or no_water_days >= 1:
        if tight_supply:
            bid = max(125.0, eff_anchor + 4.0, max_prev * 0.92)
        else:
            bid = max(105.0, eff_anchor + 2.0)
    else:
        if tight_supply:
            bid = max(98.0, eff_anchor + 3.0)
        elif medium_supply:
            bid = max(78.0, min(110.0, eff_anchor - 6.0))
        else:
            bid = 42.0

    if desperate_count >= 2 and tight_supply:
        bid += 10.0
    elif desperate_count == 0 and supply >= 22:
        bid -= 8.0

    if rich_count >= 2 and hp <= 4:
        bid += 8.0

    if day >= 8:
        bid += 6.0
    if day == 10:
        bid += 10.0

    min_safe_reserve = max(0.0, (10 - day) * 18.0)
    cap = budget - min_safe_reserve
    if hp <= 3 or no_water_days >= 1:
        cap = budget
    if cap < 0:
        cap = budget * 0.5

    final_bid = min(float(budget), float(cap), float(bid))
    if final_bid < 0:
        final_bid = 0.0
    return float(final_bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    if num_alive_opponents == 0:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = DAILY_SALARY * 0.55

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        average_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 0.85:
            if my_status['hp'] > 3:
                base_bid = DAILY_SALARY * 0.6
            else:
                base_bid = DAILY_SALARY * 0.95
        else:
            base_bid = max(DAILY_SALARY * 0.5, average_prev_bid * 1.05)

    if my_status['hp'] <= 2:
        base_bid = DAILY_SALARY * 0.99
    elif my_status['no_water_days'] > 0:
        base_bid = DAILY_SALARY * 0.9

    if day_context['day'] >= EPISODE_DAYS - 2:
        base_bid = max(base_bid, DAILY_SALARY * 0.75)

    total_water_needed = sum([o['water_requirement'] for o in alive_opponents] + [WATER_REQ])
    if day_context['supply'] < total_water_needed:
        base_bid = max(base_bid, DAILY_SALARY * 0.8)

    final_bid = min(my_status['budget'], base_bid)
    return max(0.0, final_bid)
